UPDATE train_terminal_session
SET status = 'ERROR', error_code = #{errorCode}, closed_at = #{closedAt}
WHERE session_uuid = #{sessionUuid}

UPDATE train_terminal_session
SET status = 'CLOSED', close_reason = #{closeReason}, closed_at = #{closedAt}
WHERE session_uuid = #{sessionUuid} AND status = 'ACTIVE'
